node -e 'const fs=require("fs"),p=require("path");
const bad=[];
const code=(f)=>fs.readFileSync(f,"utf8").split(String.fromCharCode(10)).filter((l)=>!/^\s*(\/\/|\/?\*|\{\/\*)/.test(l)).join(String.fromCharCode(10));
const walk=(d,out=[])=>{for(const e of fs.readdirSync(d,{withFileTypes:true})){if(e.name==="node_modules")continue;const q=p.join(d,e.name);if(e.isDirectory())walk(q,out);else if(/\.tsx$/.test(e.name)&&!/\.test\./.test(e.name)&&e.name!=="loading.tsx")out.push(q)}return out};
const files=[...walk("app"),...walk("components")];
const src=new Map(files.map((f)=>[f,code(f)]));
const renders=(tag)=>files.filter((f)=>new RegExp("<"+tag+"\\b").test(src.get(f)));
const WRAPPERS={"components/templates/event-detail-template.tsx":"EventDetailTemplate","components/templates/journey-detail-template.tsx":"JourneyDetailTemplate"};
const COMPOSED={"PosterBand":"components/media/poster-band.tsx"};
const composes=(s)=>Object.entries(COMPOSED).some(([tag,file])=>new RegExp("<"+tag+"\\b").test(s)&&fs.existsSync(file)&&/<PageHero\b/.test(code(file)));
const on=(f,s)=>{const page=p.join(p.dirname(f),"page.tsx");const sib=f!==page&&fs.existsSync(page)?code(page):"";return /<FqEventCover\b/.test(s??src.get(f))||/resolve(Detail|Identity)Hero\(/.test((s??src.get(f))+sib)||/<PageHero\b/.test(s??src.get(f))||composes(s??src.get(f))};
const rows=renders("DetailTemplate").filter((f)=>!(f in WRAPPERS)).map((f)=>({file:f,via:null,on:on(f)}));
for(const [w,tag] of Object.entries(WRAPPERS))for(const c of renders(tag))rows.push({file:c,via:w,on:on(c)||on(w)});
const RULED=[];
const off=rows.filter((r)=>!r.on);
const stray=off.filter((r)=>!RULED.includes(r.via??r.file));
if(stray.length)bad.push("a DetailTemplate surface hand-rolls its cover off the PageHero grammar: "+stray.map((r)=>r.file).join(", "));
for(const f of RULED){if(!fs.existsSync(f))bad.push("ruled exception is gone, shrink the list: "+f);else if(on(f))bad.push("ruled exception now composes the grammar, shrink the list: "+f)}
if(rows.length<15)bad.push("census sees only "+rows.length+" DetailTemplate surfaces, so it is reading the wrong tree");
const seed="app/(main)/circles/starter/[slug]/page.tsx";
if(!fs.existsSync(seed)||!on(seed))bad.push("POSITIVE CONTROL FAILED: the starter Circle page no longer reads as on the grammar");
else if(on(seed,code(seed).replace(/resolveDetailHero\(/g,"x(").replace(/<PageHero\b/g,"<X")))bad.push("POSITIVE CONTROL FAILED: the classifier is blind to a planted off-grammar page");
if(bad.length){console.error(bad.join("; "));process.exit(1)}
console.log("PROG-P5 ok: "+rows.length+" DetailTemplate surfaces, "+(rows.length-off.length)+" on the PageHero grammar, "+off.length+" via the "+RULED.length+" ruled compositions");'
